<script setup lang="ts">
const api=useApi(); const q=ref('')
const { data: orgs }=await useAsyncData('admin-orgs',()=>api.request<any[]>('/admin/orgs').catch(()=>[]))
const filtered=computed(()=> (orgs.value||[]).filter(o=>!q.value||`${o.name} ${o.slug} ${o.type}`.toLowerCase().includes(q.value.toLowerCase())))
</script>
<template><div><div class="mb-5 flex flex-col gap-3 md:flex-row md:items-end md:justify-between"><div><p class="label-mono text-signal-deep">Accounts</p><h1 class="mt-1 font-display text-[clamp(2.2rem,3vw,2.7rem)] font-semibold tracking-[-.045em]">Customers.</h1><p class="mt-1 text-[11.5px] text-ink/45">Operators, utilities, contractors, manufacturers and homeowners.</p></div><input v-model="q" class="a-input md:w-64" placeholder="Search organisations"></div><div class="a-card overflow-hidden"><table class="w-full text-left text-[11px]"><thead class="border-b border-ink/10 bg-paper"><tr class="font-mono text-[7.5px] uppercase tracking-[.08em] text-ink/35"><th class="px-4 py-2.5">Organisation</th><th class="px-4 py-2.5">Type</th><th class="px-4 py-2.5">Plan</th><th class="px-4 py-2.5">Miles</th><th class="px-4 py-2.5">Status</th><th class="px-4 py-2.5">Joined</th></tr></thead><tbody><tr v-for="o in filtered" :key="o._id" class="border-t border-ink/10 hover:bg-paper/60"><td class="px-4 py-3"><p class="font-medium">{{ o.name }}</p><p class="font-mono text-[8px] text-ink/30">{{ o.slug }}</p></td><td class="px-4 py-3 capitalize">{{ o.type }}</td><td class="px-4 py-3 capitalize">{{ o.plan }}</td><td class="px-4 py-3">{{ o.miles }}</td><td class="px-4 py-3"><StatusPill :status="o.status"/></td><td class="px-4 py-3 text-ink/40">{{ shortDate(o.createdAt) }}</td></tr></tbody></table></div></div></template>
